using Microsoft.AspNetCore.Components.Authorization;
using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Pages;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Components;
using ShipmentTracker.Components.Account;
using ShipmentTracker.Data;
using ShipmentTracker.Services;

var builder = WebApplication.CreateBuilder(args);

// Add services to the container.
builder.Services.AddRazorComponents()
    .AddInteractiveServerComponents()
    .AddInteractiveWebAssemblyComponents()
    .AddAuthenticationStateSerialization();

builder.Services.AddSingleton<IShipmentService, ServerShipmentService>();

arguments.old_str:
// Add additional endpoints required by the Identity /Account Razor components.
app.MapAdditionalIdentityEndpoints();

app.Run();

arguments.new_str:
// Add additional endpoints required by the Identity /Account Razor components.
app.MapAdditionalIdentityEndpoints();

// Shipment API endpoints
var shipments = app.MapGroup("api/shipments").RequireAuthorization();

shipments.MapGet("/", async (IShipmentService svc) =>
    Results.Ok(await svc.GetAllShipmentsAsync()));

shipments.MapGet("/track/{trackingNumber}", async (string trackingNumber, IShipmentService svc) =>
{
    var shipment = await svc.GetShipmentByTrackingNumberAsync(trackingNumber);
    return shipment is not null ? Results.Ok(shipment) : Results.NotFound();
});

shipments.MapGet("/customer/{email}", async (string email, IShipmentService svc) =>
    Results.Ok(await svc.GetShipmentsByCustomerAsync(email)));

shipments.MapPut("/{id:int}/status", async (int id, ShipmentStatus status, IShipmentService svc) =>
{
    await svc.UpdateShipmentStatusAsync(id, status);
    return Results.NoContent();
});

app.Run();

